<script setup lang="ts">import {computed} from 'vue';import {Plus,ArrowUpRight} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import RunSummary from '../components/RunSummary.vue';import GroupProfiles from '../components/GroupProfiles.vue';import Notice from '../components/common/Notice.vue';const s=useResearchData(),auth=useAuth(),run=computed(()=>s.runs.find(r=>r.status==='completed'));</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">COMPOSITION DESK / 01</p><h1>组成研究总览<span>相对份额之间，先核对几何与假设。</span></h1></div><RouterLink v-if="auth.user?.role!=='viewer'" class="outline" to="/configure"><Plus :size="15"/>建立组成研究</RouterLink></div><Notice :message="s.error" @retry="s.refresh"/><template v-if="run"><RunSummary :run="run"/><div class="overview-grid"><section class="evidence-sheet"><div class="section-top"><span class="eyebrow">LATEST GROUP PROFILE</span><RouterLink :to="'/results?run='+run.id">读取组间证据 <ArrowUpRight :size="13"/></RouterLink></div><GroupProfiles :result="run.result"/></section><aside class="reading"><span class="eyebrow">INTERPRETATION NOTE / 01</span><h2>闭合后的差异，<br/>不是原因。</h2><p>百分比的约束会改变相关关系。CLR距离比较相对结构，δ替换需要保留为显式假设。</p><hr/><b>{{s.studies.reduce((n,x)=>n+x.sample_count,0)}}</b><span>独立样本 / {{s.studies.length}}研究</span><p>组间差异可能受组内离散度影响。这里只给描述，未正式检验同质性。</p><RouterLink to="/inputs">核对相份额与零值 →</RouterLink></aside></div></template><p v-else class="empty">先核对相份额、预定义组与零数，再创建置换研究。</p><div class="section-heading"><h2>组成册页</h2><span>3工艺 / 五相通道 / 独立合成样本</span></div><div class="study-list"><RouterLink v-for="study in s.studies" :key="study.id" :to="'/inputs?study='+study.id"><span class="eyebrow">{{study.code}}</span><div><h3>{{study.name}}</h3><p>{{study.sample_count}}样本 / {{study.component_count}}成分 / {{study.zero_rows}}行含零</p></div><b :class="study.supported?'supported':'warning'">{{study.supported?'可比较':'SST=0 / 拒绝'}}</b></RouterLink></div></div></template>
